/**
 * pages/Watchlist.jsx
 * Theo dõi cổ phiếu theo nhóm ngành / vốn hóa.
 */
import React, { useEffect, useState, useCallback } from 'react';
import {
  getWatchlistGroups, createWatchlistGroup, deleteWatchlistGroup,
  addWatchlistItem, deleteWatchlistItem, seedWatchlist, syncWatchlistPrices,
} from '../api/client';

const TYPE_LABELS = { SECTOR: 'Ngành', MARKET_CAP: 'Vốn hóa', CUSTOM: 'Tùy chỉnh' };

const GROUP_COLORS = [
  '#22c55e', '#3b82f6', '#f59e0b', '#ef4444',
  '#8b5cf6', '#ec4899', '#14b8a6', '#6366f1', '#f97316',
];

function ChangeCell({ value, pct }) {
  if (value === null || value === undefined) {
    return <span className="text-gray-600 text-xs">—</span>;
  }
  const isUp = value > 0;
  const isDown = value < 0;
  const color = isUp ? 'text-green-400' : isDown ? 'text-red-400' : 'text-gray-400';
  const sign = isUp ? '+' : '';
  return (
    <span className={`${color} font-medium tabular-nums`}>
      {sign}{typeof value === 'number' ? value.toFixed(2) : value}
      {pct !== null && pct !== undefined && (
        <span className="ml-1 text-xs opacity-80">
          ({sign}{typeof pct === 'number' ? pct.toFixed(2) : pct}%)
        </span>
      )}
    </span>
  );
}

function formatPrice(val) {
  if (val === null || val === undefined) return <span className="text-gray-600">—</span>;
  return (
    <span className="text-gray-200 tabular-nums">
      {Number(val).toLocaleString('vi-VN')}
    </span>
  );
}

export default function WatchlistPage() {
  const [groups, setGroups] = useState([]);
  const [activeId, setActiveId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [seeding, setSeeding] = useState(false);
  const [syncMsg, setSyncMsg] = useState('');

  // Form thêm mã
  const [newSymbol, setNewSymbol] = useState('');
  const [addingSymbol, setAddingSymbol] = useState(false);
  const [symbolError, setSymbolError] = useState('');

  // Form tạo nhóm
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [newGroupName, setNewGroupName] = useState('');
  const [newGroupType, setNewGroupType] = useState('CUSTOM');
  const [newGroupColor, setNewGroupColor] = useState('#22c55e');
  const [creatingGroup, setCreatingGroup] = useState(false);

  const fetchGroups = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getWatchlistGroups();
      setGroups(res.data);
      if (res.data.length > 0 && !activeId) {
        setActiveId(res.data[0].id);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [activeId]);

  useEffect(() => { fetchGroups(); }, []); // eslint-disable-line

  const activeGroup = groups.find((g) => g.id === activeId) || null;

  // Tính thống kê của nhóm đang xem
  const groupStats = activeGroup
    ? activeGroup.items.reduce(
        (acc, item) => {
          if (item.change_pct !== null) {
            if (item.change_pct > 0) acc.up++;
            else if (item.change_pct < 0) acc.down++;
            else acc.flat++;
          }
          return acc;
        },
        { up: 0, down: 0, flat: 0 },
      )
    : null;

  const handleSeed = async () => {
    setSeeding(true);
    setSyncMsg('');
    try {
      const res = await seedWatchlist();
      setSyncMsg(res.data.message);
      await fetchGroups();
    } catch {
      setSyncMsg('Tạo nhóm mặc định thất bại.');
    } finally {
      setSeeding(false);
      setTimeout(() => setSyncMsg(''), 4000);
    }
  };

  const handleSync = async () => {
    setSyncing(true);
    setSyncMsg('');
    try {
      const res = await syncWatchlistPrices(5);
      setSyncMsg(`Đã sync ${res.data.total_symbols} mã.`);
      await fetchGroups();
    } catch {
      setSyncMsg('Đồng bộ thất bại.');
    } finally {
      setSyncing(false);
      setTimeout(() => setSyncMsg(''), 4000);
    }
  };

  const handleAddSymbol = async (e) => {
    e.preventDefault();
    const sym = newSymbol.trim().toUpperCase();
    if (!sym || !activeId) return;
    setAddingSymbol(true);
    setSymbolError('');
    try {
      await addWatchlistItem(activeId, sym);
      setNewSymbol('');
      await fetchGroups();
    } catch (err) {
      setSymbolError(err.response?.data?.detail || `Không thể thêm ${sym}.`);
    } finally {
      setAddingSymbol(false);
    }
  };

  const handleDeleteItem = async (itemId, symbol) => {
    if (!window.confirm(`Xóa ${symbol} khỏi nhóm?`)) return;
    try {
      await deleteWatchlistItem(itemId);
      await fetchGroups();
    } catch {
      alert('Xóa thất bại.');
    }
  };

  const handleDeleteGroup = async (groupId, groupName) => {
    if (!window.confirm(`Xóa nhóm "${groupName}" và toàn bộ mã trong đó?`)) return;
    try {
      await deleteWatchlistGroup(groupId);
      const remaining = groups.filter((g) => g.id !== groupId);
      setGroups(remaining);
      setActiveId(remaining[0]?.id || null);
    } catch {
      alert('Xóa nhóm thất bại.');
    }
  };

  const handleCreateGroup = async (e) => {
    e.preventDefault();
    if (!newGroupName.trim()) return;
    setCreatingGroup(true);
    try {
      const res = await createWatchlistGroup({
        name: newGroupName.trim(),
        group_type: newGroupType,
        color: newGroupColor,
      });
      setGroups((prev) => [...prev, { ...res.data, items: [] }]);
      setActiveId(res.data.id);
      setShowCreateForm(false);
      setNewGroupName('');
    } catch {
      alert('Tạo nhóm thất bại.');
    } finally {
      setCreatingGroup(false);
    }
  };

  return (
    <div className="p-6 space-y-5 max-w-6xl mx-auto">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="text-xl font-bold text-gray-100">Watchlist</h1>
        <div className="flex items-center gap-2 flex-wrap">
          {syncMsg && <span className="text-xs text-brand-500">{syncMsg}</span>}

          {groups.length === 0 && !loading && (
            <button
              onClick={handleSeed}
              disabled={seeding}
              className="bg-brand-600 hover:bg-brand-700 disabled:opacity-50 text-white
                         text-sm font-semibold px-4 py-2 rounded-lg transition-colors"
            >
              {seeding ? 'Đang tạo...' : 'Nạp nhóm mặc định'}
            </button>
          )}

          <button
            onClick={handleSync}
            disabled={syncing || groups.length === 0}
            className="flex items-center gap-1.5 bg-gray-800 hover:bg-gray-700 disabled:opacity-40
                       border border-gray-700 text-sm text-gray-300 px-4 py-2 rounded-lg transition-colors"
          >
            {syncing ? (
              <>
                <span className="w-3.5 h-3.5 border-2 border-gray-500 border-t-brand-500
                                 rounded-full animate-spin inline-block" />
                Đang sync...
              </>
            ) : 'Đồng bộ giá'}
          </button>

          <button
            onClick={() => setShowCreateForm((v) => !v)}
            className="bg-gray-800 hover:bg-gray-700 border border-gray-700
                       text-sm text-gray-300 px-4 py-2 rounded-lg transition-colors"
          >
            {showCreateForm ? 'Huỷ' : '+ Tạo nhóm'}
          </button>
        </div>
      </div>

      {/* Form tạo nhóm mới */}
      {showCreateForm && (
        <form
          onSubmit={handleCreateGroup}
          className="bg-gray-900 border border-gray-800 rounded-xl p-4 flex flex-wrap items-end gap-3"
        >
          <div>
            <label className="block text-xs text-gray-400 mb-1">Tên nhóm</label>
            <input
              type="text" value={newGroupName}
              onChange={(e) => setNewGroupName(e.target.value)}
              required placeholder="VD: Ngân hàng"
              className="bg-gray-800 border border-gray-700 rounded-md px-3 py-2
                         text-sm text-gray-100 w-44 focus:outline-none focus:ring-1 focus:ring-brand-500"
            />
          </div>
          <div>
            <label className="block text-xs text-gray-400 mb-1">Loại</label>
            <select
              value={newGroupType} onChange={(e) => setNewGroupType(e.target.value)}
              className="bg-gray-800 border border-gray-700 rounded-md px-3 py-2
                         text-sm text-gray-100 focus:outline-none focus:ring-1 focus:ring-brand-500"
            >
              <option value="SECTOR">Nhóm ngành</option>
              <option value="MARKET_CAP">Nhóm vốn hóa</option>
              <option value="CUSTOM">Tùy chỉnh</option>
            </select>
          </div>
          <div>
            <label className="block text-xs text-gray-400 mb-1">Màu</label>
            <div className="flex gap-1.5">
              {GROUP_COLORS.map((c) => (
                <button
                  key={c} type="button"
                  onClick={() => setNewGroupColor(c)}
                  className={`w-6 h-6 rounded-full border-2 transition-transform ${
                    newGroupColor === c ? 'border-white scale-110' : 'border-transparent'
                  }`}
                  style={{ backgroundColor: c }}
                />
              ))}
            </div>
          </div>
          <button
            type="submit" disabled={creatingGroup}
            className="bg-brand-600 hover:bg-brand-700 disabled:opacity-50 text-white
                       font-semibold px-4 py-2 rounded-lg text-sm transition-colors"
          >
            {creatingGroup ? 'Đang tạo...' : 'Tạo nhóm'}
          </button>
        </form>
      )}

      {loading ? (
        <div className="space-y-3">
          {[...Array(3)].map((_, i) => (
            <div key={i} className="h-10 bg-gray-800 rounded-lg animate-pulse" />
          ))}
        </div>
      ) : groups.length === 0 ? (
        /* Empty state */
        <div className="flex flex-col items-center justify-center py-20 text-center">
          <div className="w-16 h-16 rounded-full bg-gray-800 flex items-center justify-center mb-4">
            <svg className="w-8 h-8 text-gray-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5}
                d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5}
                d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
            </svg>
          </div>
          <p className="text-gray-300 font-semibold">Chưa có nhóm watchlist nào</p>
          <p className="text-gray-500 text-sm mt-1">Nhấn "Nạp nhóm mặc định" để tạo các nhóm ngành Việt Nam có sẵn</p>
          <button
            onClick={handleSeed} disabled={seeding}
            className="mt-4 bg-brand-600 hover:bg-brand-700 text-white font-semibold
                       px-5 py-2 rounded-lg text-sm transition-colors disabled:opacity-50"
          >
            {seeding ? 'Đang tạo...' : 'Nạp nhóm mặc định'}
          </button>
        </div>
      ) : (
        <div className="flex gap-5">
          {/* Sidebar: danh sách nhóm */}
          <aside className="w-44 flex-shrink-0 space-y-1">
            {groups.map((g) => {
              const isActive = g.id === activeId;
              const upCount = g.items.filter((i) => i.change_pct > 0).length;
              const downCount = g.items.filter((i) => i.change_pct < 0).length;
              return (
                <button
                  key={g.id}
                  onClick={() => setActiveId(g.id)}
                  className={`w-full text-left px-3 py-2.5 rounded-lg transition-colors
                    border ${isActive
                      ? 'bg-gray-800 border-gray-600'
                      : 'border-transparent hover:bg-gray-900/70'}`}
                >
                  <div className="flex items-center gap-2">
                    <span
                      className="w-2.5 h-2.5 rounded-full flex-shrink-0"
                      style={{ backgroundColor: g.color }}
                    />
                    <span className={`text-sm font-medium truncate ${isActive ? 'text-gray-100' : 'text-gray-400'}`}>
                      {g.name}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 mt-1 pl-4.5 text-xs">
                    <span className="text-gray-600">{g.items.length} mã</span>
                    {upCount > 0 && <span className="text-green-500">▲{upCount}</span>}
                    {downCount > 0 && <span className="text-red-500">▼{downCount}</span>}
                  </div>
                </button>
              );
            })}
          </aside>

          {/* Content: bảng mã CK của nhóm đang chọn */}
          {activeGroup && (
            <div className="flex-1 min-w-0">
              {/* Group header */}
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-3">
                  <span
                    className="w-4 h-4 rounded-full flex-shrink-0"
                    style={{ backgroundColor: activeGroup.color }}
                  />
                  <div>
                    <h2 className="text-base font-bold text-gray-100">{activeGroup.name}</h2>
                    {activeGroup.description && (
                      <p className="text-xs text-gray-500">{activeGroup.description}</p>
                    )}
                  </div>
                  <span className="text-xs bg-gray-800 text-gray-400 px-2 py-0.5 rounded-full">
                    {TYPE_LABELS[activeGroup.group_type]}
                  </span>
                </div>
                <button
                  onClick={() => handleDeleteGroup(activeGroup.id, activeGroup.name)}
                  className="text-xs text-gray-600 hover:text-red-400 transition-colors"
                >
                  Xóa nhóm
                </button>
              </div>

              {/* Stats bar */}
              {groupStats && activeGroup.items.length > 0 && (
                <div className="flex items-center gap-4 mb-3 text-xs">
                  <span className="text-gray-500">{activeGroup.items.length} mã</span>
                  <span className="text-green-400">▲ Tăng: {groupStats.up}</span>
                  <span className="text-red-400">▼ Giảm: {groupStats.down}</span>
                  <span className="text-gray-500">— Không đổi: {groupStats.flat}</span>
                </div>
              )}

              {/* Bảng mã CK */}
              <div className="bg-gray-900 border border-gray-800 rounded-xl overflow-hidden">
                {activeGroup.items.length === 0 ? (
                  <div className="py-10 text-center text-gray-500 text-sm">
                    Nhóm này chưa có mã nào. Thêm mã bên dưới.
                  </div>
                ) : (
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-gray-800">
                        {['Mã CK', 'Giá đóng cửa', 'Thay đổi', '% thay đổi', 'Ngày', ''].map((h) => (
                          <th key={h} className="px-4 py-3 text-left text-xs text-gray-500 uppercase tracking-wider font-medium whitespace-nowrap">
                            {h}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-800/60">
                      {activeGroup.items.map((item) => {
                        const isUp = item.change_pct > 0;
                        const isDown = item.change_pct < 0;
                        const rowBg = isUp
                          ? 'hover:bg-green-900/10'
                          : isDown
                          ? 'hover:bg-red-900/10'
                          : 'hover:bg-gray-800/40';
                        return (
                          <tr key={item.id} className={`transition-colors ${rowBg}`}>
                            <td className="px-4 py-3">
                              <span
                                className="font-bold text-sm px-2 py-0.5 rounded"
                                style={{
                                  backgroundColor: activeGroup.color + '22',
                                  color: activeGroup.color,
                                }}
                              >
                                {item.symbol}
                              </span>
                            </td>
                            <td className="px-4 py-3">{formatPrice(item.current_price)}</td>
                            <td className="px-4 py-3">
                              <ChangeCell value={item.change_value} pct={null} />
                            </td>
                            <td className="px-4 py-3">
                              {item.change_pct !== null ? (
                                <span className={`font-bold tabular-nums ${
                                  isUp ? 'text-green-400' : isDown ? 'text-red-400' : 'text-gray-400'
                                }`}>
                                  {isUp ? '+' : ''}{item.change_pct?.toFixed(2)}%
                                </span>
                              ) : (
                                <span className="text-gray-600 text-xs">Chưa sync</span>
                              )}
                            </td>
                            <td className="px-4 py-3 text-gray-600 text-xs whitespace-nowrap">
                              {item.last_date || '—'}
                            </td>
                            <td className="px-4 py-3">
                              <button
                                onClick={() => handleDeleteItem(item.id, item.symbol)}
                                className="text-gray-700 hover:text-red-400 text-xs transition-colors"
                              >
                                ✕
                              </button>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                )}

                {/* Thêm mã */}
                <div className="border-t border-gray-800 px-4 py-3">
                  <form onSubmit={handleAddSymbol} className="flex items-center gap-2">
                    <input
                      type="text"
                      value={newSymbol}
                      onChange={(e) => { setNewSymbol(e.target.value.toUpperCase()); setSymbolError(''); }}
                      placeholder="Thêm mã CK (VD: VNM)"
                      maxLength={10}
                      className="bg-gray-800 border border-gray-700 rounded-md px-3 py-1.5
                                 text-sm text-gray-100 w-44 focus:outline-none focus:ring-1 focus:ring-brand-500
                                 placeholder-gray-600"
                    />
                    <button
                      type="submit"
                      disabled={addingSymbol || !newSymbol.trim()}
                      className="bg-brand-600 hover:bg-brand-700 disabled:opacity-50 text-white
                                 text-xs font-semibold px-3 py-1.5 rounded-md transition-colors"
                    >
                      {addingSymbol ? '...' : 'Thêm'}
                    </button>
                    {symbolError && <span className="text-red-400 text-xs">{symbolError}</span>}
                  </form>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
